import{z as d,x as i,o as r,c as B,q as s,j as E,D as l,d as n,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"向量处理器与 lane","description":"","frontmatter":{"title":"向量处理器与 lane","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vector-lanes.md","filePath":"cs/vector-lanes.md","lastUpdated":1791413859000}'),p={name:"cs/vector-lanes.md"};function c(D,a,m,h,f,u){const t=i("Mermaid");return r(),B("div",null,[a[2]||(a[2]=s('<h1 id="向量处理器与-lane" tabindex="-1">向量处理器与 lane <a class="header-anchor" href="#向量处理器与-lane" aria-label="Permalink to &quot;向量处理器与 lane&quot;">​</a></h1><div class="epigraph"><p>一条向量指令对寄存器里的一列元素流水；lane 是并行的 ALU 切片，元素间没有指令级的译码，只有数据通路的重复。</p><footer>—— 据 Russell, The CRAY-1 Computer System；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/dataflow-dae">上一课</a> 用队列藏延迟。<a href="/cs/flynn-taxonomy">Flynn</a> 的 SIMD 格还没有硬件形状。ISA 对照已有 <a href="/cs/rvv-vector">RVV</a> 与 <a href="/cs/simd-extensions">SIMD 扩展</a>。本课不重讲 token。缺口是<strong>向量机：向量寄存器、条带挖掘、lane，以及它与乱序标量核的分工。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>科学循环里相邻迭代几乎无控制相关。超标量仍要为每条 <code>add</code> 付取指与重命名。<a href="/cs/vliw-epic">VLIW</a> 要把它们打进束。向量：编译器或程序员发一条 <code>vadd</code>，硬件在 lane 上对 <code>vl</code> 个元素流水。缺口不是 MIMD 核数，而是<strong>把循环的内层变成数据通路宽度。</strong></p><p><span class="marginnote">Cray-1：向量寄存器、链式、内存条带。当代 CPU 的 AVX 是短向量；RVV 把 <code>vl</code> 做成架构状态。GPU 的 SIMT 下一课用 warp 包装类似的 lane。</span></p><p><span class="marginnote">直觉类比：把一条向量指令想象成一条灌装生产线——译码只开一次机，随后传送带把 16 瓶元素依次送过 4 个并列的灌装头（lane）。标量超标量则像 16 个工人各开各的机器装一瓶，产品一样，开机（取指译码）次数差了 16 倍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>向量寄存器文件切成 lane：lane \\(i\\) 处理元素 \\(i, i+L, \\ldots\\)。访存单元按步长从内存条带取，对齐则满带宽，散乱则退化。掩码处理条件循环，避免把 SIMD 拆成标量。链式：前一条的结果元素直接进下一条，不必等整向量写回。</p>',9)),(r(),E(A,null,{default:l(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VADD%5B%22%E4%B8%80%E6%9D%A1%20vadd%22%5D%20--%3E%20L0%5B%22lane%200%22%5D%0A%20%20VADD%20--%3E%20L1%5B%22lane%201%22%5D%0A%20%20VADD%20--%3E%20LN%5B%22lane%20L-1%22%5D%0A%20%20MEM%5B%22%E6%9D%A1%E5%B8%A6%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20L0%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">阿姆达尔</a> 的 \\(f\\) 是不可向量化段（以及 gather 失败）。向量长度覆盖延迟：足够长则流水充满，MLP 来自多个未完成的向量内存包。与乱序标量：标量核跑控制与余数，向量单元跑内核。不要在这里写张量核训练循环——那是 DSA 与大模型栏的边界，本课只到通用向量。</p><p>条带冲突：多个 lane 同时打同一 DRAM bank 会把向量访存串行化，表面上「已向量化」仍落在带宽墙内侧。这与 GPU <a href="/cs/memory-coalescing">合并</a> 是同一几何，只是粒度是向量寄存器而不是 warp。</p><p><span class="marginnote">数字实例：向量寄存器 512 位、元素 64 位，一条 vadd 覆盖 8 个元素；用 4 条 lane，每条只做 2 次 ALU 运算，8 个元素的取指译码成本只有 1 次指令发射——「每次操作的能量」从按指令摊变成按向量摊，这正是省电与提速的共同来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU warp 调度写完，下一课 SIMT。也不把脉动阵列的空间流水当成向量寄存器。RVV 的具体编码已在 ISA 课，这里只留微结构：lane 与内存条带。</p><p>后课默认：规则数据并行优先用向量/SIMD 通路。把 lane 绑到大量线程、用掩码处理分支，是 GPU SIMT。</p>',7)),(r(),E(A,null,{default:l(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOP%5B%22%E5%86%85%E5%B1%82%E5%BE%AA%E7%8E%AF%20vl%20%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%20--%3E%20STRIP%7B%22%E6%98%AF%E5%90%A6%E8%A7%84%E5%88%99%E6%9D%A1%E5%B8%A6%3F%22%7D%0A%20%20STRIP%20--%20%22%E8%BF%9E%E7%BB%AD%E5%AF%B9%E9%BD%90%22%20--%3E%20UNIT%5B%22%E5%8D%95%E5%85%83%E6%AD%A5%E9%95%BF%E8%AE%BF%E5%AD%98%2C%20%E6%BB%A1%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20STRIP%20--%20%22%E8%B7%B3%E8%B7%83%E6%88%96%E6%95%A3%E4%B9%B1%22%20--%3E%20GATHER%5B%22gather%2Fscatter%2C%20%E5%B8%A6%E5%AE%BD%E9%80%80%E5%8C%96%22%5D%0A%20%20UNIT%20--%3E%20LANE%5B%22lane%20%E5%B9%B6%E8%A1%8C%E6%B5%81%E6%B0%B4%22%5D%0A%20%20GATHER%20--%3E%20LANE%0A%20%20LANE%20--%3E%20MASK%7B%22%E6%9C%89%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF%3F%22%7D%0A%20%20MASK%20--%20%22%E6%98%AF%22%20--%3E%20VMASK%5B%22%E6%8E%A9%E7%A0%81%E5%85%83%E7%B4%A0%E7%BD%AE%E6%97%A0%E6%95%88%2C%20%E4%B8%8D%E6%8B%86%E6%A0%87%E9%87%8F%22%5D%0A%20%20MASK%20--%20%22%E5%90%A6%22%20--%3E%20DONE%5B%22%E6%95%B4%E5%90%91%E9%87%8F%E5%86%99%E5%9B%9E%22%5D%0A%20%20VMASK%20--%3E%20DONE%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为代码标上「已向量化」就万事大吉，实际上 gather/scatter 与 bank 冲突会让内存端把并行的 lane 串成一队——先看访存模式是不是规则条带，再谈 lane 数，否则向量单元在等数据。")],-1)),a[5]||(a[5]=e("h2",{id:"小结",tabindex:"-1"},[n("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[6]||(a[6]=e("ul",null,[e("li",null,"向量指令在 lane 上流水，取指开销按整条向量摊。"),e("li",null,"条带与对齐决定内存带宽；掩码处理条件。"),e("li",null,"GPU 用 warp 共享 PC 驱动类似 lane，下一课。"),e("li",null,[n("出处：Russell, Cray-1；Hennessy and Patterson, "),e("em",null,"CA:AQA"),n("。")])],-1))])}const P=d(p,[["render",c]]);export{T as __pageData,P as default};
